def rule_city_after_argued_submitted_header(doc: dict) -> list[dict]:
    try:
        import re

        lines = doc.get("lines") or []
        if not isinstance(lines, list):
            return []

        header_re = re.compile(r"\b(argued|submitted|resubmitted)\b", re.I)
        city_re = re.compile(r"^[A-Z][A-Za-z0-9'.-]*(?: [A-Z][A-Za-z0-9'.-]*)*, [A-Z][A-Za-z .'-]{2,}$")

        def norm_text(x):
            return (x or "").strip()

        for idx, line in enumerate(lines[:120]):
            text = norm_text(line.get("text"))
            if not text or not header_re.search(text):
                continue
            if not re.search(r"\b\d{4}\b", text):
                continue
            for nxt in lines[idx + 1 : idx + 5]:
                nxt_text = norm_text(nxt.get("text"))
                if not nxt_text:
                    continue
                if city_re.match(nxt_text):
                    out = {"text": nxt_text}
                    if "page_no" in nxt:
                        out["page_no"] = nxt.get("page_no")
                    if "line_no" in nxt:
                        out["line_no"] = nxt.get("line_no")
                    return [out]
                if "Filed" in nxt_text or "Before:" in nxt_text:
                    break
        return []
    except Exception:
        return []

import re


_ROLE_RE = re.compile(
    r"(?is)^\s*(?:Hon\.?\s*)?(?P<name>.+?)\s*,\s*"
    r"(?:(?:United States\s+|U\.S\.\s+)?(?:Chief|Senior)\s+)?"
    r"(?:United States\s+|U\.S\.\s+)?District Judge(?:,\s*|\s+)Presiding\s*[\.\*\u2020]*\s*$"
)
_MAGISTRATE_RE = re.compile(
    r"(?is)^\s*(?:Hon\.?\s*)?(?P<name>.+?)\s*,\s*"
    r"(?:United States\s+|U\.S\.\s+)?Magistrate Judge(?:,\s*|\s+)Presiding\s*[\.\*\u2020]*\s*$"
)
_BANKRUPTCY_RE = re.compile(
    r"(?is)^\s*(?:Hon\.?\s*)?(?P<name>.+?)\s*,\s*"
    r"(?:United States\s+|U\.S\.\s+)?Bankruptcy Judges?(?:,\s*|\s+)Presiding\s*[\.\*\u2020]*\s*$"
)

_ROLE_HINT_RE = re.compile(
    r"(?i)\b(?:(?:chief|senior)\s+)?district judge\b|\bmagistrate judge\b|\bbankruptcy judges?\b"
)
_NAMEISH_RE = re.compile(
    r"(?i)^\s*(?:Hon\.?\s*)?[A-Z][A-Za-z0-9.'’\-]*(?:\s+[A-Z][A-Za-z0-9.'’\-]*){0,6}\s*,?\s*$"
)
_NAME_FRAGMENT_RE = re.compile(
    r"(?i)^\s*(?:Hon\.?\s*)?[A-Z][^,\n]*(?:,\s*[^,\n]+)*(?:,\s*and| and|,|&)\s*$"
)
_NON_NAME_HINT_RE = re.compile(
    r"(?i)\b(?:appeal|appeals|district court|bankruptcy appellate panel|bankruptcy court|"
    r"court of appeals|before:|summary|opinion|argued|submitted|filed|before|"
    r"circuit judge|circuit judges|district judge|magistrate judge|bankruptcy judge|"
    r"appellant|appellee|plaintiff|defendant|panel|court|district\b|for the\b)\b"
)


def rule_presiding_district_judge(doc: dict) -> list[dict]:
    try:
        spans = []
        seen = set()

        def add_name(raw_name: str, source_item: dict) -> None:
            name = re.sub(r"(?i)^\s*Hon\.?\s*", "", raw_name or "").strip()
            name = name.strip(" \t\r\n,.;:*")
            name = re.sub(r"\s+", " ", name).strip()
            if not name:
                return
            key = name.lower()
            if key in seen:
                return
            seen.add(key)
            span = {"text": name}
            for field in ("page_no", "line_no", "paragraph_no"):
                if field in source_item:
                    span[field] = source_item[field]
            spans.append(span)

        def find_match(text: str) -> str | None:
            normalized = re.sub(r"\s+", " ", (text or "")).strip()
            if not normalized:
                return None
            for pat in (_ROLE_RE, _MAGISTRATE_RE, _BANKRUPTCY_RE):
                match = pat.match(normalized)
                if match:
                    return match.group("name")
            return None

        def scan_items(items: list[dict]) -> None:
            limit = min(len(items or []), 120)

            def is_nameish(text: str) -> bool:
                normalized = re.sub(r"\s+", " ", text or "").strip()
                if not normalized or _NON_NAME_HINT_RE.search(normalized):
                    return False
                return bool(_NAMEISH_RE.match(normalized) or _NAME_FRAGMENT_RE.match(normalized))

            for i in range(limit):
                item = items[i] or {}
                text = (item.get("text") or "").strip()
                if not text:
                    continue

                has_role_hint = bool(_ROLE_HINT_RE.search(text))
                has_presiding = "presiding" in text.lower()
                prev_text = ((items[i - 1] or {}).get("text") or "").strip() if i > 0 else ""
                next_text = ((items[i + 1] or {}).get("text") or "").strip() if i + 1 < limit else ""

                direct_name = find_match(text)
                if direct_name and not (has_role_hint or has_presiding):
                    add_name(direct_name, item)
                    continue

                candidates = []

                if prev_text and is_nameish(prev_text):
                    candidates.append((f"{prev_text} {text}", items[i - 1] or item))

                if next_text and is_nameish(next_text):
                    candidates.append((f"{text} {next_text}", item))

                if prev_text and next_text and is_nameish(prev_text):
                    candidates.append((f"{prev_text} {text} {next_text}", items[i - 1] or item))

                if prev_text and next_text and is_nameish(next_text):
                    candidates.append((f"{prev_text} {text} {next_text}", item))

                matched = False
                for candidate_text, candidate_source in candidates:
                    candidate_name = find_match(candidate_text)
                    if candidate_name:
                        add_name(candidate_name, candidate_source)
                        matched = True
                        break

                if matched:
                    continue

                if direct_name:
                    add_name(direct_name, item)

        scan_items(doc.get("lines") or [])
        scan_items(doc.get("paragraphs") or [])

        if len(spans) > 1 and not any(
            any(sep in (span.get("text") or "") for sep in (",", " and ", ";"))
            for span in spans
        ):
            aggregate_text = "; ".join(span.get("text") or "" for span in spans if span.get("text"))
            if aggregate_text:
                aggregate_key = aggregate_text.lower()
                if aggregate_key not in seen:
                    seen.add(aggregate_key)
                    aggregate_span = {"text": aggregate_text}
                    first_span = spans[0]
                    for field in ("page_no", "line_no", "paragraph_no"):
                        if field in first_span:
                            aggregate_span[field] = first_span[field]
                    spans.insert(0, aggregate_span)

        if not spans:
            full_text = re.sub(r"\s+", " ", doc.get("text") or "").strip()
            if full_text:
                for pat in (_ROLE_RE, _MAGISTRATE_RE, _BANKRUPTCY_RE):
                    match = pat.search(full_text)
                    if match:
                        add_name(match.group("name"), {})
                        break

        return spans
    except Exception:
        return []

import re


_MONTH_NAME_RE = (
    r"(?:January|February|March|April|May|June|July|August|September|"
    r"October|November|December)"
)
_DATE_LONG_RE = re.compile(rf"^{_MONTH_NAME_RE} \d{{1,2}}, \d{{4}}$")
_DATE_ABBR_RE = re.compile(r"^[A-Z]{3} \d{1,2} \d{4}$")
_FILED_LONG_RE = re.compile(rf"^Filed ({_MONTH_NAME_RE} \d{{1,2}}, \d{{4}})$")
_FILED_ABBR_RE = re.compile(r"^Filed ([A-Z]{3} \d{1,2} \d{4})$")


def _as_int(value):
    try:
        return int(value)
    except Exception:
        return value


def _iter_header_lines(doc, max_pages=12, max_lines=100):
    pages = doc.get("pages") or []
    if pages:
        pages = sorted(pages, key=lambda x: _as_int(x.get("page_no", 0)))
        for page in pages[:max_pages]:
            page_no = _as_int(page.get("page_no", 0))
            text = page.get("text") or ""
            for idx, raw_line in enumerate(text.splitlines()[:max_lines], start=1):
                yield {"page_no": page_no, "line_no": idx, "text": raw_line}
        return

    lines = doc.get("lines") or []
    if lines:
        lines = sorted(
            lines,
            key=lambda x: (
                _as_int(x.get("page_no", 0)),
                _as_int(x.get("line_no", 0)),
            ),
        )
        current_page = None
        seen_pages = 0
        for line in lines:
            page_no = _as_int(line.get("page_no", 0))
            if page_no != current_page:
                current_page = page_no
                seen_pages += 1
                if seen_pages > max_pages:
                    break
            if _as_int(line.get("line_no", 0)) > max_lines:
                continue
            yield line


def _make_span(line, text=None):
    span = {
        "text": line.get("text", "") if text is None else text,
    }
    if "page_no" in line:
        span["page_no"] = line["page_no"]
    if "line_no" in line:
        span["line_no"] = line["line_no"]
    return span


def rule_on_what_date_was_this_opinion_filed(doc: dict) -> list[dict]:
    try:
        full_text = doc.get("text") or ""

        # Withdrawn-opinion orders often say "The Opinion filed <date> ..." and
        # the question is asking about that underlying opinion, not the order itself.
        m = re.search(
            rf"\bThe Opinion filed ({_MONTH_NAME_RE} \d{{1,2}}, \d{{4}}|[A-Z]{{3}} \d{{1,2}} \d{{4}})",
            full_text,
        )
        if m and (re.search(r"\bFILED\b", full_text) or re.search(r"\bAMENDED\b", full_text)):
            return [{"text": m.group(1)}]

        header_lines = list(_iter_header_lines(doc))
        if not header_lines:
            return []

        # The filing date usually appears on page 1 or 2, near the top of the header.
        for idx, line in enumerate(header_lines):
            text = (line.get("text") or "").strip()
            if not text:
                continue

            m = _FILED_LONG_RE.match(text) or _FILED_ABBR_RE.match(text)
            if m:
                return [_make_span(line, m.group(1))]

            if text == "FILED":
                for follow in header_lines[idx + 1 :]:
                    next_text = (follow.get("text") or "").strip()
                    if not next_text:
                        continue
                    if _DATE_LONG_RE.match(next_text) or _DATE_ABBR_RE.match(next_text):
                        return [_make_span(follow)]
                    break

            if _DATE_LONG_RE.match(text) or _DATE_ABBR_RE.match(text):
                return [_make_span(line)]

        # Fallback for unusual layouts.
        for pat in (_FILED_LONG_RE, _FILED_ABBR_RE):
            m = pat.search(full_text)
            if m:
                return [{"text": m.group(1)}]

        m = re.search(rf"\n({_MONTH_NAME_RE} \d{{1,2}}, \d{{4}}|[A-Z]{{3}} \d{{1,2}} \d{{4}})\n", full_text)
        if m:
            return [{"text": m.group(1)}]

        return []
    except Exception:
        return []

def rule_court_of_appeals_docket_numbers(doc: dict) -> list[dict]:
    try:
        import re

        lines = doc.get("lines") or []
        spans = []
        seen = set()

        docket_re = re.compile(r"\b\d{1,2}(?:A)?-\d{1,6}(?:-\d{1,6})?\b")
        label_only_re = re.compile(r"(?i)^Nos?\.?$")
        label_anywhere_re = re.compile(r"(?i)\bNos?\.?")

        def add_matches(text: str, line: dict) -> None:
            for match in docket_re.finditer(text):
                value = match.group(0).rstrip(".,;:")
                key = (line.get("page_no"), line.get("line_no"), value)
                if key in seen:
                    continue
                seen.add(key)
                span = {"text": value}
                if "page_no" in line:
                    span["page_no"] = line["page_no"]
                if "line_no" in line:
                    span["line_no"] = line["line_no"]
                spans.append(span)

        limit = min(len(lines), 60)

        for i in range(limit):
            line = lines[i] or {}
            text = (line.get("text") or "").strip()
            if not text:
                continue
            if text.upper().startswith("D.C."):
                continue

            if label_anywhere_re.search(text):
                if docket_re.search(text):
                    add_matches(text, line)
                    if text.rstrip().endswith(",") or text.rstrip().endswith(";"):
                        for j in range(i + 1, min(limit, i + 6)):
                            next_line = lines[j] or {}
                            next_text = (next_line.get("text") or "").strip()
                            if not next_text:
                                continue
                            if next_text.upper().startswith("D.C."):
                                continue
                            if docket_re.search(next_text):
                                add_matches(next_text, next_line)
                    continue

                if label_only_re.fullmatch(text):
                    for j in range(i + 1, min(limit, i + 6)):
                        next_line = lines[j] or {}
                        next_text = (next_line.get("text") or "").strip()
                        if not next_text:
                            continue
                        if next_text.upper().startswith("D.C."):
                            continue
                        if docket_re.search(next_text):
                            add_matches(next_text, next_line)

        return spans
    except Exception:
        return []

def rule_city_from_oral_argument_order_phrase(doc: dict) -> list[dict]:
    try:
        import re

        lines = doc.get("lines") or []
        if not isinstance(lines, list):
            return []

        lines = sorted(
            [line for line in lines if isinstance(line, dict)],
            key=lambda x: (x.get("page_no", 0), x.get("line_no", 0)),
        )

        trigger_re = re.compile(
            r"(reschedule oral argument|oral argument to the week|submission for this case is vacated|submission is vacated)",
            re.I,
        )
        city_line_re = re.compile(
            r"^[A-Z][A-Za-z0-9'.-]*(?: [A-Z][A-Za-z0-9'.-]*)*, [A-Z][A-Za-z .'-]{2,}$"
        )

        def clean(text: str) -> str:
            return (text or "").strip().rstrip(" .;:")

        for idx, line in enumerate(lines[:80]):
            window = [clean(line.get("text", ""))]
            for nxt in lines[idx + 1 : idx + 3]:
                window.append(clean(nxt.get("text", "")))
            text = " ".join(part for part in window if part)
            if not text or not trigger_re.search(text):
                continue
            m = re.search(r"\bin\s+([A-Z][^.;:\n]+)", text)
            if m:
                city_text = clean(m.group(1))
                if not city_line_re.match(city_text):
                    continue
                out = {"text": city_text}
                if "page_no" in line:
                    out["page_no"] = line.get("page_no")
                if "line_no" in line:
                    out["line_no"] = line.get("line_no")
                return [out]
            for nxt in lines[idx + 1 : idx + 4]:
                nxt_text = clean(nxt.get("text", ""))
                if city_line_re.match(nxt_text):
                    out = {"text": nxt_text}
                    if "page_no" in nxt:
                        out["page_no"] = nxt.get("page_no")
                    if "line_no" in nxt:
                        out["line_no"] = nxt.get("line_no")
                    return [out]
        return []
    except Exception:
        return []

